#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Effects;
using MVZ2Logic;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Modding;
using MVZ2Logic.Options;
using MVZ2Logic.Sponsors;
using PVZEngine.Callbacks;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class SponsorsGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(LogicLevelCallbacks.POST_USE_ENTITY_BLUEPRINT, EnginePostUseEntityBlueprintCallback);
        }
        private void EnginePostUseEntityBlueprintCallback(LogicLevelCallbacks.PostUseEntityBlueprintParams param, CallbackResultVoid callbackResult)
        {
            if (!Global.Options.ShowSponsorNames())
                return;
            var output = param.placeOutput;
            var entity = output.entity;
            if (entity == null)
                return;
            if (output.placeDefinition == null)
                return;
            var entityID = output.placeDefinition.GetID();
            if (entityID == VanillaContraptionID.furnace)
            {
                ShowFurnaceSponsorName(entity);
            }
            else if (entityID == VanillaContraptionID.moonlightSensor)
            {
                ShowMoonlightSensorSponsorName(entity);
            }
            else if (entityID == VanillaContraptionID.gunpowderBarrel)
            {
                ShowGunpowderBarrelSensorSponsorName(entity);
            }
        }
        private void ShowFurnaceSponsorName(Entity furnace)
        {
            var names = Global.Sponsors.GetSponsorPlanNames(SponsorPlans.Furnace.TYPE, SponsorPlans.Furnace.FURNACE);
            if (names.Length <= 0)
                return;
            var rng = new RandomGenerator(furnace.InitSeed);
            var name = names.Random(rng);
            var param = new SpawnParams();
            param.SetProperty(FloatingText.PROP_TEXT, name);
            furnace.Spawn(VanillaEffectID.floatingText, furnace.GetCenter(), param);
        }
        private void ShowMoonlightSensorSponsorName(Entity sensor)
        {
            var names = Global.Sponsors.GetSponsorPlanNames(SponsorPlans.Sensor.TYPE, SponsorPlans.Sensor.MOONLIGHT_SENSOR);
            if (names.Length <= 0)
                return;
            var rng = new RandomGenerator(sensor.InitSeed);
            var name = names.Random(rng);
            var param = new SpawnParams();
            param.SetProperty(FloatingText.PROP_TEXT, name);
            sensor.Spawn(VanillaEffectID.floatingText, sensor.GetCenter(), param);
        }
        private void ShowGunpowderBarrelSensorSponsorName(Entity barrel)
        {
            var names = Global.Sponsors.GetSponsorPlanNames(SponsorPlans.Furnace.TYPE, SponsorPlans.Furnace.GUNPOWDER_BARREL);
            if (names.Length <= 0)
                return;
            var rng = new RandomGenerator(barrel.InitSeed);
            var name = names.Random(rng);
            var param = new SpawnParams();
            param.SetProperty(FloatingText.PROP_TEXT, name);
            barrel.Spawn(VanillaEffectID.floatingText, barrel.GetCenter(), param);
        }
    }
}
